import pytest
from candidate import median

def test_median_odd_numbers():
    assert median([3, 1, 2, 4, 5]) == 3

def test_median_even_numbers():
    result = median([-10, 4, 6, 1000, 10, 20])
    assert result == 15.0
    assert isinstance(result, float)

def test_median_single_element():
    assert median([42]) == 42

def test_median_unsorted_list():
    assert median([9, 1, 8, 2, 7, 3, 6, 4, 5]) == 5

def test_median_with_floats():
    assert median([1.5, 2.5, 3.5]) == 2.5
    assert median([1.5, 2.5, 3.5, 4.5]) == 3.0

def test_median_negative_numbers():
    assert median([-5, -1, -3]) == -3
    assert median([-5, -1, -3, -2]) == -2.5

def test_median_duplicates():
    assert median([2, 2, 2, 2, 2]) == 2
    assert median([1, 2, 2, 4]) == 2.0

def test_median_string_list():
    assert median(['c', 'a', 'b']) == 'b'
    assert median(['d', 'a', 'c', 'b']) == 'b'

def test_median_mixed_int_float():
    assert median([1, 2.5, 3]) == 2.5
    assert median([1, 3, 2.5, 4]) == 3.25

def test_median_preserves_original_list():
    original = [3, 1, 2, 4, 5]
    copy = original.copy()
    median(original)
    assert original == copy

def test_median_empty_list():
    with pytest.raises(IndexError):
        median([])

def test_median_none_input():
    with pytest.raises(TypeError):
        median(None)

def test_median_non_iterable_input():
    with pytest.raises(TypeError):
        median(42)

def test_median_non_comparable_elements():
    with pytest.raises(TypeError):
        median([1, 'a', 3])

def test_median_large_numbers():
    large = [1, 10**12, 5]
    assert median(large) == 5
    even_large = [1, 10**12]
    assert median(even_large) == (1 + 10**12) / 2.0
    assert isinstance(median(even_large), float)
